sys_script_include.script:
var FleetReservationActions = Class.create();
FleetReservationActions.prototype = {
    // FLEET-37 (D-03, D-24): the only documented exception to the reservation write ACL (FLEET-62).
    // Changes reservation_state, cancellation_reason, late_cancellation (+ activity) only.
    RES: 'x_1850693_enterp_0_reservation',
    CANCELLABLE: ['DRAFT', 'PENDING_APPROVAL', 'APPROVED', 'PENDING_ASSIGNMENT', 'WAITLISTED', 'ASSIGNED', 'READY_FOR_PICKUP'],
    BEFORE_APPROVAL: ['DRAFT', 'PENDING_APPROVAL'],

    initialize: function() {},

    /**
     * Cancels a reservation after checking the caller and the rules.
     * @param {string} reservationId
     * @param {string} reason - mandatory
     * @param {Object} [options] - {system: true} for system cancellations (FLEET-36 waitlist expiry, FLEET-65 termination)
     * @returns {{ok: boolean, message: string}}
     */
    cancel: function(reservationId, reason, options) {
        options = options || {};
        reason = (reason || '').trim();
        if (!reason) {
            return this._fail('A cancellation reason is required.');
        }
        var res = new GlideRecord(this.RES);
        if (!res.get(reservationId)) {
            return this._fail('Reservation not found.');
        }
        var state = res.getValue('reservation_state');
        if (this.CANCELLABLE.indexOf(state) < 0) {
            return this._fail('Reservations in state ' + state + ' cannot be cancelled.');
        }

        var actor = this._actor(res, options);
        if (!actor) {
            return this._fail('You are not allowed to cancel this reservation.');
        }

        var late = false;
        var recipients = [];
        var dispatchers = this._groupId('Fleet Dispatchers');
        if (actor.type == 'requester') {
            if (this.BEFORE_APPROVAL.indexOf(state) < 0) {
                var hoursToStart = (new GlideDateTime(res.getValue('start_datetime')).getNumericValue() -
                    new GlideDateTime().getNumericValue()) / 3600000;
                late = hoursToStart < FleetConfig.get('cancellation.grace_hours'); // D-03: no hold, vehicle released now
                recipients = [res.getValue('manager_approver'), dispatchers];
            }
        } else {
            recipients = [res.getValue('requested_by')]; // cancelled by someone else (manager, dispatcher, director, system)
        }

        res.setValue('reservation_state', 'CANCELLED');
        res.setValue('cancellation_reason', reason);
        res.setValue('late_cancellation', late);
        res.work_notes = 'Cancelled by ' + actor.label + (late ? ' (late cancellation)' : '') + ': ' + reason;
        if (!res.update()) {
            return this._fail('The reservation could not be cancelled.');
        }
        new FleetWaitlist().process(); // FLEET-36: the released vehicle may serve a waitlisted request
        gs.eventQueue('x_1850693_enterp_0.reservation.cancelled', res, this._clean(recipients).join(','), actor.label);
        return { ok: true, message: 'Reservation ' + res.getValue('number') + ' cancelled' + (late ? ' (late cancellation).' : '.') };
    },

    _actor: function(res, options) {
        if (options.system) {
            return { type: 'system', label: 'System' };
        }
        var sec = new FleetSecurity();
        var name = gs.getUserDisplayName();
        if (sec.isOwn(res)) {
            return { type: 'requester', label: name + ' (requester)' };
        }
        if (sec.has('director')) {
            return { type: 'director', label: name + ' (director)' };
        }
        if (sec.has('dispatcher') && sec.isMyDepot(res.getValue('requested_depot'))) {
            return { type: 'dispatcher', label: name + ' (dispatcher)' };
        }
        if (sec.isDirectReport(res)) {
            return { type: 'manager', label: name + ' (manager)' };
        }
        return null;
    },

    _groupId: function(name) {
        var g = new GlideRecord('sys_user_group');
        return g.get('name', name) ? g.getUniqueValue() : '';
    },

    _clean: function(list) {
        var out = [];
        for (var i = 0; i < list.length; i++) {
            if (list[i] && out.indexOf(list[i]) < 0) {
                out.push(list[i]);
            }
        }
        return out;
    },

    _fail: function(msg) {
        return { ok: false, message: msg };
    },

    type: 'FleetReservationActions'
};
